'use strict';
const nav=document.querySelector('#nav'),menu=document.querySelector('.menu');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú');nav.classList.remove('open');translatePage()}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='false';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');nav.classList.toggle('open',open);translatePage()});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const products={"analyst": {"title": "Una entrevista para conocer a la persona.", "description": "Ejemplo de una videollamada con IA de 30 minutos para una persona que nunca ha tenido crédito. Este demo no activa cámara ni micrófono.", "rows": [["Persona", "Andrea Martínez · Caso ficticio"], ["Historial crediticio", "Sin experiencia previa de crédito"], ["Duración de la videollamada", "30 minutos"], ["Objetivo", "Conocer su realidad económica"]]}, "assistant": {"title": "Una evaluación psicométrica en la misma llamada.", "description": "La videollamada integra una evaluación psicométrica en el proceso de crédito. Esta vista solo explica la etapa: no administra pruebas ni calcula resultados psicométricos.", "rows": [["Prami", "Cuéntame a qué te dedicas."], ["Andrea", "Trabajo por cuenta propia."], ["Prami", "¿Cómo cambian tus ingresos y cuáles son tus gastos?"], ["Objetivo", "Evaluación psicométrica integrada al proceso"]]}, "risk": {"title": "La conversación se conecta con el riesgo.", "description": "Vista ilustrativa de información que puede apoyar la evaluación de capacidad de pago. No es una evaluación real ni una recomendación de crédito.", "rows": [["Actividad económica", "Información recogida en la entrevista"], ["Ingresos y gastos", "Información declarada por la persona"], ["Compromisos de pago", "Contexto de la solicitud"], ["Resultado del demo", "Sin puntaje ni decisión real"]]}, "capture": {"title": "Varios roles. Una sola evaluación.", "description": "Prami concentra la entrevista, la evaluación psicométrica y el análisis de riesgo en una videollamada de 30 minutos.", "rows": [["Tipo de crédito", "Crédito para personas"], ["Entrevista", "Conversación guiada por IA"], ["Evaluación psicométrica", "Información más allá del historial"], ["Análisis de riesgo", "Capacidad de pago con contexto"]]}};
const tabs=[...document.querySelectorAll('[data-tab]')],panel=document.querySelector('#workspace-panel');function selectProduct(key,focus=false){const product=products[key];tabs.forEach(t=>{const active=t.dataset.tab===key;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;if(active&&focus)t.focus()});panel.setAttribute('aria-labelledby','tab-'+key);panel.innerHTML='<h3>'+product.title+'</h3><p>'+product.description+'</p><div class="workspace-detail">'+product.rows.map(([a,b])=>'<div><span>'+a+'</span><strong>'+b+'</strong></div>').join('')+'</div>';translatePage()}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectProduct(tab.dataset.tab));tab.addEventListener('keydown',e=>{let index;if(e.key==='ArrowRight'||e.key==='ArrowDown')index=(i+1)%tabs.length;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')index=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();selectProduct(tabs[index].dataset.tab,true)})});selectProduct('analyst');
function explore(key='analyst'){selectProduct(key);document.querySelector('#plataforma').scrollIntoView();panel.focus({preventScroll:true})}document.querySelectorAll('[data-explore]').forEach(b=>b.addEventListener('click',()=>explore()));document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>explore(b.dataset.product)));
const contact=document.querySelector('#contact');document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>contact.showModal()));document.querySelector('.close').addEventListener('click',()=>contact.close());document.querySelector('#explore-from-contact').addEventListener('click',()=>{const keys=['analyst','assistant','risk','capture','analyst'];const key=keys[document.querySelector('#interest').selectedIndex];contact.close();explore(key)});contact.addEventListener('click',e=>{if(e.target===contact){const r=contact.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)contact.close()}});
